r = dict(name='Binocular',user=c['user'],season=str(c['season']),week=int(c['nfl_week']),reviewed_at=now.astimezone(ZoneInfo('America/Detroit')).date().isoformat(),updated_at=now.isoformat(),valid_until=(now+timedelta(hours=24)).isoformat(),expires_after='2026-10-06',scope='September 30 Week 4 review. Live ownership and dated sources checked; Sunday/Monday game designations remain pending. The user confirmed the current lineup was built with Claude; it is preserved as the chosen baseline. Claude model outputs were not inspected or validated here. No custom-scoring projections or moves executed.',sources=sources,leagues={},candidates=[dict(name=n,role='Ownership and role watch',sources=['sleeper','waiver']) for n in ['Daniel Jones','Braelon Allen','Ollie Gordon','Jaylen Wright','Kendre Miller','Harold Fannin','Juwan Johnson','Quinshon Judkins']],changes=['Replaced obsolete claims and departed-player advice with current rosters.','Jacked Pine: preserve chosen Stroud lineup; flag Hurts comparison and confirm Warren Thursday case.','Netanyahu Ball: completed Bowers trade and Allen acquisition reflected; Collins contingency added.','MSU: Jones/Gordon additions reflected; Fannin Thursday plan and Washington kickoff decisions reviewed.'])
