    scoring,trade,watch=notes[lid]
    lineup=[dict(slot=slot,id=pid,name=players[pid]['name'],position=players[pid]['position'],team=players[pid]['team'],note='User-selected current lineup; see research alternatives, injury conditions and kickoff notes.') for slot,pid in zip(team['slots'],starters)]
    moves=plans[lid]
    r['leagues'][lid]=dict(name=league['name'],headline=moves[0]['title'],strategy='Retain useful cover; make injury-dependent decisions before the relevant kickoff.',scoring_note=scoring,scoring_baseline=league['scoring'],slots_baseline=league['slots'],roster_ids=sorted(p['id'] for p in league['roster']),lineup=lineup,calls=[dict(kind=m['action'],title=m['title'],reason=m['reason'],confidence=m['confidence'],sources=m['sources'],recheck=m['cost']) for m in moves],lineup_notes=[dict(title='Trade and waiver review',body=trade,sources=['sleeper','value','waiver']),dict(title='Other lineup and reserve decisions',body=watch,sources=['sleeper','schedule','pit']),dict(title='Timing and uncertainty',body='No Week 4 byes or games already locked. Thursday players lock October 1 at 8:15 p.m. ET. Sunday/Monday final inactives are not yet available. Never treat a blank cached injury flag as proof of health.',sources=['schedule'])],player_moves=moves,trades=[],watch=watch)
